def validate(text: str) -> list[str]:
    """List what is wrong with a raw ticket (empty, too_long, no_letters); empty list means ok."""
    problems = []
    if not text or not text.strip():
        problems.append("empty: the message has no text")
        return problems
    if len(text) > MAX_CHARS:
        problems.append(f"too_long: over {MAX_CHARS} characters")
    if not any(ch.isalpha() for ch in text):
        problems.append("no_letters: the message has no letters")
    return problems

def predict_proba(self, texts: list[str]) -> np.ndarray:
    """Return shape (n, 77) probabilities in taxonomy.INTENTS order, scores divided by the temperature."""
    return _softmax(self.scores(texts) / self.temperature)

def decide(proba: np.ndarray, oov_rate: float, th: Thresholds) -> Decision:
    """Turn one row of 77 probabilities into a Decision using the thresholds.

    Why teams are summed: a ticket can be confusing between two card intents yet clearly a
    card ticket, so the team is often safe to route even when the intent is not.
    """
    order = np.argsort(-proba)
    top = [{"intent": INTENTS[i], "prob": float(proba[i])} for i in order[:5]]
    team_probs = team_probabilities(proba)
    team = max(team_probs, key=lambda t: team_probs[t])
    p_high = float(proba[HIGH_INDEX].sum())
    if p_high >= th.tau_high:
        urgency = "high"
    else:
        urgency = "medium" if proba[MEDIUM_INDEX].sum() >= proba[LOW_INDEX].sum() else "low"
    team_conf = team_probs[team]
    if team_conf < th.tau_team:
        decision, reason = "human", "low_confidence"
    elif oov_rate > th.oov_max and team_conf < th.oov_conf:
        decision, reason = "human", "unfamiliar_words"
    else:
        decision, reason = "auto", "ok"
    return Decision(
        intent=INTENTS[order[0]], intent_conf=float(proba[order[0]]), top_intents=top,
        team=team, team_conf=team_conf, team_probs=team_probs, urgency=urgency,
        p_high=p_high, decision=decision, reason=reason,
    )

def save_review(sessions: sessionmaker, ticket_id: int, body: ReviewIn,
                created_at: datetime | None = None) -> Review:
    """Store one review and mark the ticket reviewed, all or nothing.

    Raises TicketNotFound (404), BadReview (422) or AlreadyReviewed (409).
    """
    if body.action == "override" and body.final_intent is not None and body.final_intent not in INTENTS:
        raise BadReview(f"unknown intent: {body.final_intent}")
    with sessions() as session:
        pred = session.scalars(select(Prediction).where(Prediction.ticket_id == ticket_id)).first()
    if pred is None:
        raise TicketNotFound(f"ticket {ticket_id} not found")
    intent, urgency = _final_values(body, pred)
    try:
        with sessions() as session, session.begin():
            _claim_and_insert(session, ticket_id, body, intent, urgency, created_at)
    except (AlreadyReviewed, IntegrityError):
        raise AlreadyReviewed(f"ticket {ticket_id} was already reviewed") from None
    with sessions() as session:
        row = session.scalars(select(ReviewRow).where(ReviewRow.ticket_id == ticket_id)).one()
        return review_to_schema(row)
